package ama.transcript;
import ama.storage.*;import ama.contract.StorageContracts.*;
import ama.contract.FileContracts.*;
import ama.audit.AuditPort;
import ama.task.OutboxPort;
import java.util.*;
import java.io.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Actual upload commands and TransactionRunner, substituted SELECT-only JDBC/storage/ACL. */
class Task11UploadPublicationGuardTest {
 static final String M=Task11PublicationWriteGuardBoundaryTest.MEETING,U="12345678-1234-4234-8234-123456789ac7",F="12345678-1234-4234-8234-123456789ac8",H="a".repeat(64);
 static final class Case {
  final Task11PublicationWriteGuardBoundaryTest.Fixture f;final PublicationWriteGuard guard;final FileBackendCatalog backends=mock(FileBackendCatalog.class);final JdbcFileUploads uploads;String state="COMPLETED";boolean acceptedPart=true;
  Case()throws Exception{f=new Task11PublicationWriteGuardBoundaryTest.Fixture();guard=spy(f.guard);when(f.authority.publicationBudget()).thenAnswer(x->new TranscriptAcquisitionBudget(16777216,16777216,16777216,268435456,134217728,33554432,128,256,256).ledger(f.authority.readBudget(),f.authority.canonicalBudget(),()->false));when(f.access.lock(Task11PublicationWriteGuardBoundaryTest.ACTOR,M)).thenReturn(f.root);
   f.responder=sql->{if(sql.startsWith("SELECT meeting_id FROM upload_session"))return List.of(Map.of("meeting_id",M));if(sql.startsWith("SELECT * FROM upload_session")){if(f.updates.stream().anyMatch(x->x.contains("state='ABORTED'")))state="ABORTED";return List.of(Task11ImportPublicationGuardTest.row("id",U,"meeting_id",M,"backend_id","local","namespace","files","object_key","ab/upload","cancel_epoch",0L,"expected_size",8L,"expected_sha256",H,"provider_upload_token","token","state",state,"completed_file_id",state.equals("COMPLETED")?F:null,"display_name","source.txt","purpose","TRANSCRIPT_INPUT"));}if(sql.contains(" FROM upload_part "))return acceptedPart?List.of(Task11ImportPublicationGuardTest.row("part_no",1L,"size_bytes",8L,"sha256",H,"provider_token","part")):List.of();return null;};
   uploads=new JdbcFileUploads(f.ds,f.tx,f.access,(a,m,p)->{},backends,mock(AuditPort.class),mock(OutboxPort.class),8,guard);
  }
 }
 @Test void acknowledgedPartAfterFreezeReturnsBeforeNewGuardPreparationOrStorage()throws Exception{var c=new Case();c.f.frozen.set(true);c.uploads.part(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,1,new ByteArrayInputStream(new byte[0]),8,H,"trace");verify(c.guard,never()).prepare(any(),anyString());verifyNoInteractions(c.backends);}
 @Test void acknowledgedCompletionAfterFreezeReturnsBeforeNewGuardPreparationOrStorage()throws Exception{var c=new Case();c.f.frozen.set(true);assertEquals(F,c.uploads.complete(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,new Completion(List.of(new ClientPart(1,H)),H),"trace").fileId());verify(c.guard,never()).prepare(any(),anyString());verifyNoInteractions(c.backends);}
 @Test void changedAcknowledgedPartConflictsAndRevocationStillDenies()throws Exception{var c=new Case();c.f.frozen.set(true);assertThrows(Conflict.class,()->c.uploads.part(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,1,new ByteArrayInputStream(new byte[0]),9,H,"trace"));doThrow(new ama.access.MeetingAccess.AccessDeniedException()).when(c.f.access).require(c.f.root,ama.access.MeetingAccess.Action.EDIT);assertThrows(ama.access.MeetingAccess.AccessDeniedException.class,()->c.uploads.complete(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,new Completion(List.of(new ClientPart(1,H)),H),"trace"));verifyNoInteractions(c.backends);}
 @Test void newPartIsFencedBeforeAnyStorageCall()throws Exception{var c=new Case();c.state="OPEN";c.acceptedPart=false;c.f.frozen.set(true);assertThrows(Conflict.class,()->c.uploads.part(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,1,new ByteArrayInputStream(new byte[8]),8,H,"trace"));verifyNoInteractions(c.backends);}
 static FileStoragePort storage(Case c){var backend=mock(FileBackendCatalog.Backend.class);var storage=mock(FileStoragePort.class);when(backend.storage()).thenReturn(storage);when(backend.type()).thenReturn("LOCAL");when(c.backends.require(eq("local"),anyBoolean())).thenReturn(backend);return storage;}
 @Test void ordinaryNewPartCommitsAfterFreshGuardAndLateFreezeLeavesNoReceipt()throws Exception{
  for(boolean race:List.of(false,true)){var c=new Case();c.state="OPEN";c.acceptedPart=false;c.f.allowUpdates=true;var storage=storage(c);when(storage.writePart(any(),eq(1),any(),eq(8L),eq(H))).thenAnswer(x->{if(race)c.f.frozen.set(true);return new PartReceipt(1,8,H,"part");});
   if(race)assertThrows(Conflict.class,()->c.uploads.part(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,1,new ByteArrayInputStream(new byte[8]),8,H,"trace"));else c.uploads.part(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,1,new ByteArrayInputStream(new byte[8]),8,H,"trace");assertEquals(race?0:1,c.f.updates.size());if(!race)assertTrue(c.f.updates.getFirst().contains("upload_part"));else assertEquals(1,c.f.rollbacks.get());verify(storage).writePart(any(),eq(1),any(),eq(8L),eq(H));
  }
 }
 @Test void racingAcceptedPartRemainsAnAcknowledgmentEvenAfterFreeze()throws Exception{var c=new Case();c.state="OPEN";c.acceptedPart=false;var storage=storage(c);when(storage.writePart(any(),eq(1),any(),eq(8L),eq(H))).thenAnswer(x->{c.f.frozen.set(true);c.acceptedPart=true;return new PartReceipt(1,8,H,"part");});c.uploads.part(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,1,new ByteArrayInputStream(new byte[8]),8,H,"trace");assertTrue(c.f.updates.isEmpty());}
 @Test void completionFinalGatePreventsFrozenBlobAttachment()throws Exception{for(boolean race:List.of(false,true)){var c=new Case();c.state="FINALIZING";c.f.allowUpdates=true;var storage=storage(c);when(storage.complete(any(),anyList(),eq(H))).thenAnswer(x->{if(race)c.f.frozen.set(true);return new StoredBlob(new StorageKey("local","files","ab/upload"),8,H,"version");});if(race)assertThrows(Conflict.class,()->c.uploads.complete(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,new Completion(List.of(new ClientPart(1,H)),H),"trace"));else assertNotNull(c.uploads.complete(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,new Completion(List.of(new ClientPart(1,H)),H),"trace").fileId());assertEquals(race?0:4,c.f.updates.size());}}
 @Test void frozenOpenUploadMayStillUseAuthorizedAbortCleanup()throws Exception{var c=new Case();c.state="OPEN";c.f.frozen.set(true);c.f.allowUpdates=true;var storage=storage(c);c.uploads.abort(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,"trace");assertEquals(1,c.f.updates.size());assertTrue(c.f.updates.getFirst().contains("state='ABORTED'"));verify(storage).discardUpload(any(),eq(new StorageKey("local","files","ab/upload")));verify(c.guard,never()).prepare(any(),anyString());}
 @Test void acknowledgedBeginAfterFreezePrecedesHistoryAndRejectsChangedBody()throws Exception{var c=new Case();c.f.frozen.set(true);var original=c.f.responder;String requestHash=uploadHash("file-init-v1","TRANSCRIPT_INPUT","source.txt","8",H);c.f.responder=sql->sql.contains(" FROM idempotency_record ")?List.of(Task11ImportPublicationGuardTest.row("actor_id","owner","resource_id",M,"operation","UPLOAD_BEGIN","request_hash",requestHash,"result_id",U)):original.apply(sql);assertEquals(U,c.uploads.begin(Task11PublicationWriteGuardBoundaryTest.ACTOR,M,"begin-key",new Begin("TRANSCRIPT_INPUT","source.txt",8,H),"trace").uploadId());assertThrows(Conflict.class,()->c.uploads.begin(Task11PublicationWriteGuardBoundaryTest.ACTOR,M,"begin-key",new Begin("TRANSCRIPT_INPUT","changed.txt",8,H),"trace"));verify(c.guard,never()).prepare(any(),anyString());verifyNoInteractions(c.backends);}
 @Test void physicallyCompletedButFinallyFrozenSessionCanBeCleanedRepeatedly()throws Exception{
  var c=new Case();c.state="FINALIZING";c.f.allowUpdates=true;var storage=storage(c);when(storage.complete(any(),anyList(),eq(H))).thenAnswer(x->{c.f.frozen.set(true);return new StoredBlob(new StorageKey("local","files","ab/upload"),8,H,"version");});
  assertThrows(Conflict.class,()->c.uploads.complete(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,new Completion(List.of(new ClientPart(1,H)),H),"trace"));assertEquals("FINALIZING",c.state);assertTrue(c.f.updates.isEmpty());
  assertDoesNotThrow(()->c.uploads.abort(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,"trace"));assertDoesNotThrow(()->c.uploads.abort(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,"trace"));assertEquals("ABORTED",c.state);verify(storage,times(2)).discardUpload(any(),eq(new StorageKey("local","files","ab/upload")));assertEquals(1,c.f.updates.size());assertThrows(Conflict.class,()->c.uploads.complete(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,new Completion(List.of(new ClientPart(1,H)),H),"trace"));
 }
 @Test void contradictoryAbortedAttachmentCannotReachDestructiveCleanup()throws Exception{
  var c=new Case();c.state="ABORTED";var original=c.f.responder;c.f.responder=q->{var rows=original.apply(q);if(q.startsWith("SELECT * FROM upload_session")){var row=new LinkedHashMap<>(rows.getFirst());row.put("completed_file_id",F);return List.of(row);}return rows;};storage(c);
  assertThrows(Conflict.class,()->c.uploads.abort(Task11PublicationWriteGuardBoundaryTest.ACTOR,U,"trace"));verifyNoInteractions(c.backends);assertTrue(c.f.updates.isEmpty());
 }
 static String uploadHash(String... values)throws Exception{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);for(String value:values){var raw=value.getBytes(java.nio.charset.StandardCharsets.UTF_8);out.writeInt(raw.length);out.write(raw);}return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes.toByteArray()));}

}
